import{_ as i,c as e,o as l,a2 as s}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"疑難排解","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/troubleshooting.md","filePath":"zh-TW/guide/troubleshooting.md","lastUpdated":1793163976000}'),t={name:"zh-TW/guide/troubleshooting.md"};function o(r,a,p,n,h,d){return l(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="疑難排解" tabindex="-1">疑難排解 <a class="header-anchor" href="#疑難排解" aria-label="Permalink to &quot;疑難排解&quot;">​</a></h1><p>本頁彙整 NueZip 在 macOS 上常見的問題及其解決方式。</p><h2 id="應用程式無法啟動或啟動時崩潰" tabindex="-1">應用程式無法啟動或啟動時崩潰 <a class="header-anchor" href="#應用程式無法啟動或啟動時崩潰" aria-label="Permalink to &quot;應用程式無法啟動或啟動時崩潰&quot;">​</a></h2><p>症狀：NueZip 無法開啟、立即崩潰，或顯示非預期的錯誤。</p><p>可嘗試的步驟：</p><ol><li>確認您的 macOS 版本符合最低需求（macOS 14 Sonoma 以上）。</li><li>退出並重新啟動 App。</li><li>重新啟動您的 Mac。</li><li>若 App 是從 GitHub Releases 下載的，請嘗試下載最新的建置版本或已公證的版本。</li><li>若問題持續，請蒐集日誌（見下方）並開立 issue。</li></ol><h2 id="無法開啟-rar-壓縮檔" tabindex="-1">無法開啟 RAR 壓縮檔 <a class="header-anchor" href="#無法開啟-rar-壓縮檔" aria-label="Permalink to &quot;無法開啟 RAR 壓縮檔&quot;">​</a></h2><p>症狀：NueZip 無法開啟 <code>.rar</code> 檔案，或顯示錯誤。</p><p>檢查清單：</p><ol><li>確認 RAR 檔案未損毀。請嘗試使用其他工具（例如 The Unarchiver）開啟。</li><li>多分割卷 RAR 壓縮檔必須具備所有分割部分（<code>.part1.rar</code>、<code>.part2.rar</code> 等）。</li><li>受密碼保護的 RAR 壓縮檔需要正確的密碼。</li><li>支援 RAR5 格式。若您使用的是較舊的 RAR 格式，請回報給我們。</li></ol><h2 id="解壓縮失敗並出現密碼錯誤" tabindex="-1">解壓縮失敗並出現密碼錯誤 <a class="header-anchor" href="#解壓縮失敗並出現密碼錯誤" aria-label="Permalink to &quot;解壓縮失敗並出現密碼錯誤&quot;">​</a></h2><p>症狀：解壓縮失敗並顯示「密碼錯誤」或解密錯誤。</p><p>檢查清單：</p><ol><li>確認密碼正確 — 密碼有區分大小寫。</li><li>確認支援正確的加密類型（ZIP 使用 AES-256）。</li><li>嘗試從密碼管理員重新輸入密碼。</li></ol><h2 id="finder-擴充功能未顯示" tabindex="-1">Finder 擴充功能未顯示 <a class="header-anchor" href="#finder-擴充功能未顯示" aria-label="Permalink to &quot;Finder 擴充功能未顯示&quot;">​</a></h2><p>症狀：在 Finder 中右鍵點擊壓縮檔時，沒有出現 NueZip 的選項。</p><p>檢查清單：</p><ol><li>啟用擴充功能：系統設定 → 隱私權與安全性 → 擴充功能 → Finder 擴充功能 → 啟用 <strong>NueZip</strong>。</li><li>重新啟動 Finder：在活動監視器中右鍵點擊 Finder → 重新啟動，或在終端機執行 <code>killall Finder</code>。</li><li>若擴充功能仍不出現，請重新安裝 App。</li></ol><h2 id="授權-購買未顯示" tabindex="-1">授權 / 購買未顯示 <a class="header-anchor" href="#授權-購買未顯示" aria-label="Permalink to &quot;授權 / 購買未顯示&quot;">​</a></h2><p>症狀：您已購買 NueZip，但它仍顯示為試用版。</p><p>檢查清單：</p><ol><li>確認您登入的 Apple ID 與購買時使用的相同。</li><li>恢復購買：NueZip → 設定 → 授權 → 恢復購買。</li><li>若問題持續，請聯絡支援團隊。</li></ol><h2 id="如何蒐集除錯日誌" tabindex="-1">如何蒐集除錯日誌 <a class="header-anchor" href="#如何蒐集除錯日誌" aria-label="Permalink to &quot;如何蒐集除錯日誌&quot;">​</a></h2><p>為協助診斷問題，請從 NueZip 蒐集除錯日誌：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 將日誌複製到桌面以便分享</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Desktop/NueZip-Logs</span></span></code></pre></div><p>接著在 <a href="https://github.com/nuezip/nuezip/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 開立 issue 並附上日誌。</p><h2 id="權限相關問題" tabindex="-1">權限相關問題 <a class="header-anchor" href="#權限相關問題" aria-label="Permalink to &quot;權限相關問題&quot;">​</a></h2><p>若某項功能要求權限，但在授予權限後仍無法運作：</p><ol><li>授予權限後，請退出 App 並重新開啟。</li><li>若有需要，請使用 <code>tccutil</code> 重置權限提示（請參閱<a href="./permissions.html">權限指南</a>）。</li></ol><h2 id="效能問題" tabindex="-1">效能問題 <a class="header-anchor" href="#效能問題" aria-label="Permalink to &quot;效能問題&quot;">​</a></h2><p>若 App 運作緩慢或沒有回應：</p><ol><li>關閉其他佔用資源的大型應用程式。</li><li>嘗試解壓縮較小的壓縮檔，以隔離問題。</li><li>若效能隨時間下降，請重新啟動 App。</li></ol><h2 id="檢視日誌" tabindex="-1">檢視日誌 <a class="header-anchor" href="#檢視日誌" aria-label="Permalink to &quot;檢視日誌&quot;">​</a></h2><p>為排除崩潰或問題，應用程式日誌是最有用的資訊。在沙箱化（App Store）的建置版本中，請檢查：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Containers/com.w3cub.nuezip/Data/Library/Logs/NueZip/nuezip.log</span></span></code></pre></div><h2 id="重置應用程式" tabindex="-1">重置應用程式 <a class="header-anchor" href="#重置應用程式" aria-label="Permalink to &quot;重置應用程式&quot;">​</a></h2><p>若要重置設定並清除本機資料：</p><ol><li>退出 NueZip</li><li>移除 container（請小心 — 這會刪除所有設定）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.nuezip</span></span></code></pre></div><ol start="3"><li>重新開啟 NueZip 並重新設定。</li></ol><h2 id="回報問題" tabindex="-1">回報問題 <a class="header-anchor" href="#回報問題" aria-label="Permalink to &quot;回報問題&quot;">​</a></h2><p>開立 issue 時，請包含：</p><ul><li>macOS 版本（蘋果選單 → 關於這台 Mac）</li><li>NueZip 版本（NueZip → 關於）</li><li>重現步驟</li><li>日誌（蒐集方式請參閱<a href="#view-logs">檢視日誌</a>一節）</li></ul><p>這有助於維護者更快速地找出並修復問題。</p>`,44)])])}const b=i(t,[["render",o]]);export{u as __pageData,b as default};
